package com.restaurant.pos.shift;
import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.transaction.annotation.Transactional; import jakarta.validation.constraints.*; import jakarta.validation.Valid; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/shifts") public class ShiftController { final ShiftRepository shifts; final JdbcTemplate jdbc; ShiftController(ShiftRepository s,JdbcTemplate j){shifts=s;jdbc=j;} record Open(@NotNull @DecimalMin("0") BigDecimal openingCash){} record Close(@NotNull @DecimalMin("0") BigDecimal closingCash){}
 private String id(Jwt j){return j.getSubject();} private String name(Jwt j){String n=j.getClaimAsString("name");return n==null?j.getClaimAsString("preferred_username"):n;}
 @GetMapping("/current") public Shift current(@org.springframework.security.core.annotation.AuthenticationPrincipal Jwt j){return shifts.findByWaiterIdAndStatus(id(j),"OPEN").orElse(null);} @GetMapping @PreAuthorize("hasRole('ADMIN')") public List<Shift> all(){return shifts.findAllByOrderByOpenedAtDesc();}
 @PostMapping("/open") @Transactional public Shift open(@org.springframework.security.core.annotation.AuthenticationPrincipal Jwt j,@Valid @RequestBody Open r){if(shifts.findByWaiterIdAndStatus(id(j),"OPEN").isPresent()) throw new IllegalStateException("An active shift already exists"); var s=new Shift();s.waiterId=id(j);s.waiterName=name(j);s.openingCash=r.openingCash;s.status="OPEN";s.openedAt=Instant.now();return shifts.save(s);}
 @PostMapping("/{id}/close") @Transactional public Shift close(@PathVariable Long id,@org.springframework.security.core.annotation.AuthenticationPrincipal Jwt j,@Valid @RequestBody Close r){var s=shifts.findById(id).orElseThrow(()->new IllegalArgumentException("Shift not found"));if(!s.waiterId.equals(this.id(j)) && !j.getClaimAsMap("realm_access").toString().contains("ADMIN"))throw new IllegalArgumentException("Not your shift");Integer open=jdbc.queryForObject("select count(*) from tickets where shift_id=? and status='OPEN'",Integer.class,id);if(open!=null&&open>0)throw new IllegalStateException("Close or pay all tickets before closing shift");BigDecimal payments=jdbc.queryForObject("select coalesce(sum(amount),0) from ticket_payments where shift_id=?",BigDecimal.class,id);s.expectedCash=s.openingCash.add(payments);s.closingCash=r.closingCash;s.cashDifference=r.closingCash.subtract(s.expectedCash);s.closedAt=Instant.now();s.status="CLOSED";return shifts.save(s);}
}
